using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Threading.Tasks;using System.Windows.Forms;
namespace GearLab {
 public static class TransmissionExport {
  static object Loop(CadLoop l){return l.Circle?(object)new Dictionary<string,object>{{"Circle",new[]{l.X,l.Y,l.R}}}:new Dictionary<string,object>{{"Points",l.Points.Select(p=>new[]{(double)p.X,(double)p.Y}).ToArray()}};}
  public static object Spec(CadAssembly model){if(!model.Valid)throw new Exception("Некорректная сборка.");if(model.Parts.Any(q=>q.MeshOverride!=null&&q.NativeStep==null&&q.Loft==null))throw new Exception("Есть детали только в виде сетки. Для STEP нужны параметрические сечения или исходное B-rep тело.");return model.Parts.Select(q=>new Dictionary<string,object>{{"Id",q.Id},{"Label",q.Label},{"Transform",CADNativeBridge.Transform(q.Placement)},{"Native",q.NativeStep},{"Sections",q.Loft==null?q.Sections.Select(s=>(object)new Dictionary<string,object>{{"Z0",s.Bottom},{"Z1",s.Top},{"Outer",Loop(s.Outer)},{"Holes",s.Holes.Select(Loop).ToArray()}}).ToArray():null},{"Loft",q.Loft==null?null:q.Loft.Levels.Select(l=>new Dictionary<string,object>{{"Z",l.Z},{"Outer",Loop(l.Outer)},{"Holes",l.Holes.Select(Loop).ToArray()}}).ToArray()}}).ToArray();}
  public static void Write(CadAssembly model,string path,CADKernel kernel){kernel.Run(new CADDocument(),"assembly_parametric",path,null,null,new Dictionary<string,object>{{"Spec",Spec(model)}});}
  public static void Write(CadAssembly model,string path){using(var k=new CADKernel())Write(model,path,k);}
 }
 public partial class MainForm {
  async void ExportTransmissionStep(IEnumerable<string> ids=null,string chosenPath=null){if(waveExportBusy||!ReadControls())return;Recalculate();if(!result.Valid||!result.Model.Valid)return;string path=chosenPath??dialogs.Save(this,"step","Редуктор_"+kinds[p.Kind]+".step");if(path==null)return;var snapshot=new CadAssembly();snapshot.Parts.AddRange(result.Model.Parts.Where(q=>ids==null?p.ExportScope!=2||PrintExport.Candidate(q):ids.Contains(q.Id)));waveExportBusy=true;string temp=Path.Combine(Path.GetDirectoryName(Path.GetFullPath(path)),".gearlab-"+Guid.NewGuid().ToString("N")+".step");try{if(waveCancel==null){waveCancel=new Button{Text="Отменить STEP",Width=130,Height=32};waveCancel.Click+=(s,e)=>waveExportKernel.Cancel();step.Parent.Controls.Add(waveCancel);}waveCancel.Visible=true;footer.Text="Построение B-rep из параметрических сечений…";await Task.Factory.StartNew(()=>TransmissionExport.Write(snapshot,temp,waveExportKernel));if(File.Exists(path))File.Replace(temp,path,null);else File.Move(temp,path);footer.Text="STEP сохранён: "+path;}catch(Exception ex){if(!IsDisposed)footer.Text="STEP не сохранён: "+ex.GetBaseException().Message;}finally{if(File.Exists(temp))File.Delete(temp);waveExportBusy=false;if(!IsDisposed&&waveCancel!=null)waveCancel.Visible=false;}}
 }
}
